mapper.select:
SELECT ${groupExpr} AS bucket,
       COUNT(*) AS rowCount,
       COALESCE(SUM(balance), 0) AS totalAmount
FROM bank_account
WHERE deleted = 0
  AND tenant_id = #{tenantId}

    AND account_no = #{accountNo}


    AND status = #{status}

GROUP BY ${groupExpr}
ORDER BY bucket
LIMIT #{limit}
